#[derive(Debug, PartialEq, Eq)]
pub enum Error {
    NotEnoughPinsLeft,
    GameComplete,
}

pub struct BowlingGame {
    /// Every roll taken so far, in order.
    rolls: Vec<u16>,
    /// Index of the frame currently being played (0..=9), or 10 once the
    /// game is over and only tenth-frame bonus balls remain.
    frame: usize,
    /// Number of rolls taken in the current frame (0..=2).
    rolls_in_frame: u8,
    /// Pins knocked down so far in the current frame.
    frame_pins: u16,
    /// Number of tenth-frame bonus balls still to be thrown (0..=2).
    bonus: u8,
    /// Whether the game is finished.
    done: bool,
}

impl BowlingGame {
    pub fn new() -> Self {
        Self {
            rolls: Vec::new(),
            frame: 0,
            rolls_in_frame: 0,
            frame_pins: 0,
            bonus: 0,
            done: false,
        }
    }

    pub fn roll(&mut self, pins: u16) -> Result<(), Error> {
        if self.done {
            return Err(Error::GameComplete);
        }

        if self.frame < 10 {
            // Frames 1-9: at most two rolls, and the frame's total may not
            // exceed ten pins.
            let allowed = if self.rolls_in_frame == 0 {
                10
            } else {
                10 - self.frame_pins
            };
            if pins > allowed {
                return Err(Error::NotEnoughPinsLeft);
            }

            self.rolls.push(pins);
            self.frame_pins += pins;
            self.rolls_in_frame += 1;

            if self.rolls_in_frame == 2 || self.frame_pins == 10 {
                // The frame is complete; move on.
                let was_strike = self.rolls_in_frame == 1;
                self.frame += 1;
                self.rolls_in_frame = 0;
                self.frame_pins = 0;

                if self.frame == 10 {
                    // Just finished the ninth frame: a strike earns two
                    // bonus balls, a spare earns one.
                    if was_strike {
                        self.bonus = 2;
                    } else if self.frame_pins_before() == 10 {
                        self.bonus = 1;
                    } else {
                        self.done = true;
                    }
                }
            }
        } else {
            // Tenth-frame bonus balls. The second ball is only free when the
            // first bonus ball was a strike; otherwise it is bounded by the
            // pins left from the first bonus ball.
            let last = self.rolls[self.rolls.len() - 1];
            let allowed = if self.bonus == 2 {
                10
            } else if last == 10 {
                10
            } else {
                10 - last
            };
            if pins > allowed {
                return Err(Error::NotEnoughPinsLeft);
            }

            self.rolls.push(pins);
            self.bonus -= 1;
            if self.bonus == 0 {
                self.done = true;
            }
        }

        Ok(())
    }

    pub fn score(&self) -> Option<u16> {
        if !self.done {
            return None;
        }

        let rolls = &self.rolls;
        let mut total = 0;
        let mut i = 0;

        for frame in 0..10 {
            if frame < 9 {
                if rolls[i] == 10 {
                    // Strike: 10 plus the next two rolls.
                    total += 10 + rolls[i + 1] + rolls[i + 2];
                    i += 1;
                } else if rolls[i] + rolls[i + 1] == 10 {
                    // Spare: 10 plus the next roll.
                    total += 10 + rolls[i + 2];
                    i += 2;
                } else {
                    total += rolls[i] + rolls[i + 1];
                    i += 2;
                }
            } else {
                // Tenth frame: the total pins knocked down, bonus balls
                // included.
                total += rolls[i..].iter().sum::<u16>();
            }
        }

        Some(total)
    }

    /// Pins knocked down in the frame that was just completed.
    fn frame_pins_before(&self) -> u16 {
        // The frame's rolls are the last `rolls_in_frame` entries.
        self.rolls[self.rolls.len() - self.rolls_in_frame as usize..]
            .iter()
            .sum()
    }
}

